  coredumpErased: ["The core dump was erased.", "El volcado se borró.", "Der Core-Dump wurde gelöscht.", "Le vidage a été effacé.", "Il core dump è stato cancellato.", "コアダンプを削除しました。", "核心转储已删除。", "O core dump foi apagado."],
  e_no_coredump: ["There is no core dump on this node.", "Este nodo no tiene ningún volcado.", "Dieser Knoten hat keinen Core-Dump.", "Ce nœud n'a aucun vidage.", "Questo nodo non ha alcun core dump.", "このノードにコアダンプはありません。", "此节点没有核心转储。", "Este nó não tem nenhum core dump."],
  e_bad_size: ["The file size is not valid for a firmware.", "El tamaño del archivo no es válido para un firmware.", "Die Dateigröße ist für eine Firmware ungültig.", "La taille du fichier n'est pas valide pour un firmware.", "La dimensione del file non è valida per un firmware.", "ファイルサイズがファームウェアとして正しくありません。", "文件大小不适合作为固件。", "O tamanho do ficheiro não é válido para um firmware."],
  e_not_firmware: ["That file is not an ESP32 firmware.", "Ese archivo no es un firmware de ESP32.", "Diese Datei ist keine ESP32-Firmware.", "Ce fichier n'est pas un firmware ESP32.", "Quel file non è un firmware ESP32.", "そのファイルはESP32のファームウェアではありません。", "该文件不是ESP32固件。", "Esse ficheiro não é um firmware ESP32."],
  e_image_invalid: ["The firmware image is damaged or incomplete.", "La imagen de firmware está dañada o incompleta.", "Das Firmware-Image ist beschädigt oder unvollständig.", "L'image du firmware est endommagée ou incomplète.", "L'immagine del firmware è danneggiata o incompleta.", "ファームウェアイメージが破損または不完全です。", "固件镜像已损坏或不完整。", "A imagem de firmware está danificada ou incompleta."],
  e_wrong_firmware: ["That firmware belongs to another project.", "Ese firmware es de otro proyecto.", "Diese Firmware gehört zu einem anderen Projekt.", "Ce firmware appartient à un autre projet.", "Quel firmware appartiene a un altro progetto.", "そのファームウェアは別のプロジェクトのものです。", "该固件属于其他项目。", "Esse firmware pertence a outro projeto."],
  e_upload_interrupted: ["The upload was interrupted.", "La subida se interrumpió.", "Der Upload wurde unterbrochen.", "L'envoi a été interrompu.", "Il caricamento è stato interrotto.", "アップロードが中断されました。", "上传被中断。", "O carregamento foi interrompido."],
