  p_sd_card: ["used by the microSD socket", "usado por la ranura microSD", "vom microSD-Steckplatz belegt", "utilisé par le lecteur microSD", "usato dallo slot microSD", "microSDソケットが使用中", "被microSD插槽占用", "usado pela ranhura microSD"],
  p_outside_subnet: ["outside the subnet", "fuera de la subred", "außerhalb des Subnetzes", "hors du sous-réseau", "fuori dalla sottorete", "サブネット外", "不在子网内", "fora da sub-rede"],
  // ---- searching for Wi-Fi networks, and Bluetooth
  scanNetworks: ["Search for networks", "Buscar redes", "Netzwerke suchen", "Rechercher des réseaux", "Cerca reti", "ネットワークを検索", "搜索网络", "Procurar redes"],
