  analogModeAc: ["effective value (AC)", "valor eficaz (CA)", "Effektivwert (AC)", "valeur efficace (CA)", "valore efficace (CA)", "実効値（AC）", "有效值（交流）", "valor eficaz (AC)"],
  analogScale: ["Scale (units per volt at the pin)", "Escala (unidades por voltio en el pin)", "Skala (Einheiten pro Volt am Pin)", "Échelle (unités par volt sur la broche)", "Scala (unità per volt sul pin)", "スケール（ピンの 1 V あたりの単位）", "比例（引脚上每伏对应的单位）", "Escala (unidades por volt no pino)"],
  analogScaleHint: ["A 1:11 divider is 11; a clamp that gives 1 V for 30 A is 30.", "Un divisor 1:11 es 11; una pinza que da 1 V por 30 A es 30.", "Ein Teiler 1:11 ist 11; eine Zange, die 1 V für 30 A liefert, ist 30.", "Un diviseur 1:11 vaut 11 ; une pince qui donne 1 V pour 30 A vaut 30.", "Un partitore 1:11 vale 11; una pinza che dà 1 V per 30 A vale 30.", "1:11 の分圧器なら 11、30 A で 1 V を出すクランプなら 30 です。", "1:11 分压器为 11；30 A 对应 1 V 的钳表为 30。", "Um divisor 1:11 é 11; uma pinça que dá 1 V para 30 A é 30."],
